<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { useRouter } from 'vue-router';
import { ElMessage, ElMessageBox } from 'element-plus';
import { ArrowUpRight, ClipboardCheck } from 'lucide-vue-next';
import { api } from '../api';
import { post } from '../saas';
import { useSessionStore } from '../stores/session';
import { useResponsiveDrawer } from '../province-monitoring';
import { assignmentRoles, assignmentStatuses, dateTime, matterLevels, matterStatuses, matterType, overdue, relatedTypes } from '../coordination';
import ProvincePageState from './ProvincePageState.vue';
import InspectionReportFields from './InspectionReportFields.vue';
const props=defineProps<{modelValue:boolean;matterId:string}>();
const emit=defineEmits<{'update:modelValue':[value:boolean];edit:[row:any];followUp:[row:any];changed:[]}>();
const router=useRouter(),session=useSessionStore(),width=useResponsiveDrawer(1000),detail=ref<any>(),loading=ref(false),error=ref(''),saving=ref(false);
const canWrite=computed(()=>session.user?.permissions.includes('system:organization:update'));
const canCloseAll=computed(()=>detail.value?.status!=='CLOSED'&&detail.value?.assignments?.length&&detail.value.assignments.every((row:any)=>['SUBMITTED','CLOSED'].includes(row.status))&&detail.value.assignments.some((row:any)=>row.status==='SUBMITTED'));
let version=0,controller:AbortController|undefined;
async function load(){const current=++version;controller?.abort();controller=new AbortController();loading.value=true;error.value='';detail.value=undefined;try{const value=await api<any>(`/oversight/matters/${props.matterId}`,{signal:controller.signal});if(current===version)detail.value=value;}catch(reason){if(current===version&&!controller.signal.aborted)error.value=reason instanceof Error?reason.message:'事项详情读取失败';}finally{if(current===version)loading.value=false;}}
async function act(action:string,assignment?:any){if(!detail.value||saving.value)return;let comment='';try{if(action==='DISPATCH'){await ElMessageBox.confirm(`将“${detail.value.title}”派发给 ${detail.value.assignments.length} 个地市。派发后，办理要求和责任地市将锁定。`,'确认派发',{confirmButtonText:'确认派发',cancelButtonText:'取消',type:'warning'});comment='按事项要求派发至责任地市。';}else{const label=action==='RETURN'?'退回补充':'复核办结';comment=(await ElMessageBox.prompt(`请填写${label}意见${assignment?` · ${assignment.cityName}`:''}`,label,{inputType:'textarea',inputValidator:(value:string)=>value?.trim().length>=2?true:'请填写至少2字的复核意见',confirmButtonText:'确认',cancelButtonText:'取消'})).value;}}catch{return;}saving.value=true;try{await post(`/oversight/matters/${detail.value.id}/actions`,{action,comment,workspaceId:assignment?.workspaceId});ElMessage.success(action==='DISPATCH'?'事项已派发':action==='RETURN'?'已退回属地补充':'复核结果已保存');await load();emit('changed');}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'操作未完成，请重试');}finally{saving.value=false;}}
function openRelated(){const row=detail.value?.related;if(!row)return;emit('update:modelValue',false);void router.push(row.type==='VEHICLE'?{path:'/province/vehicles',query:{vehicleId:row.id}}:row.type==='ALERT'?{path:'/province/monitoring',query:{view:'alerts',alertId:row.id}}:{path:'/province/accidents',query:{accidentId:row.id}});}
function followUp(assignment:any){emit('followUp',{...detail.value,assignment});}
watch(()=>[props.modelValue,props.matterId],()=>{if(props.modelValue&&props.matterId)void load();else{version++;controller?.abort();}},{immediate:true});
onBeforeUnmount(()=>{version++;controller?.abort();});
const logLabels:Record<string,string>={CREATE:'建立草稿',UPDATE:'修改草稿',DISPATCH:'派发事项',RESPOND:'地市响应',SUBMIT:'提交反馈',RETURN:'退回补充',CLOSE:'复核办结'};
</script>
<template><el-drawer :model-value="modelValue" :size="width" title="协同事项详情" class="coord-detail-drawer" :close-on-click-modal="!saving" @update:model-value="emit('update:modelValue',$event)"><ProvincePageState :loading="loading" :error="error" @retry="load"><template v-if="detail">
  <header class="coord-detail-heading"><div><p>{{detail.businessNo}} · {{matterType(detail)}}</p><h2>{{detail.title}}</h2></div><el-tag :type="detail.status==='CLOSED'?'success':detail.status==='PENDING_REVIEW'?'warning':'info'">{{matterStatuses[detail.status]||'待核查'}}</el-tag></header>
  <div class="coord-brief"><span>事项级别 <b>{{matterLevels[detail.level]}}</b></span><span :class="{'coord-overdue':overdue(detail)}">完成期限 <b>{{dateTime(detail.dueAt)}}</b></span><span>发起人 <b>{{detail.createdByName}}</b></span></div>
  <section class="coord-detail-section"><h3>办理要求</h3><p class="coord-prose">{{detail.description}}</p><p v-if="detail.basis" class="coord-basis">依据或线索：{{detail.basis}}</p><el-button v-if="detail.related" link type="primary" :icon="ArrowUpRight" @click="openRelated">{{relatedTypes[detail.related.type]}}：{{detail.related.businessNo}} · {{detail.related.title}}</el-button><p v-else-if="detail.relatedId" class="pm-muted">关联资料当前不可查看，请核对资料状态和查询权限。</p></section>
  <section v-if="detail.template==='SPECIAL_INSPECTION'" class="coord-detail-section"><header><h3>专项排查进展</h3><span class="pm-muted">仅汇总已提交或已办结的反馈</span></header><div v-if="detail.inspectionSummary.reportedCities" class="coord-summary-numbers"><div><span>已反馈地市</span><b>{{detail.inspectionSummary.reportedCities}} / {{detail.inspectionSummary.totalCities}}</b></div><div><span>排查企业</span><b>{{detail.inspectionSummary.enterprises}} 家</b></div><div><span>排查车辆</span><b>{{detail.inspectionSummary.vehicles}} 辆</b></div><div><span>问题车辆</span><b>{{detail.inspectionSummary.problemVehicles}} 辆</b></div><div><span>已整改车辆</span><b>{{detail.inspectionSummary.rectifiedVehicles}} 辆</b></div><div><span>整改完成率</span><b>{{detail.inspectionSummary.rectificationRate==null?'无问题车辆':`${detail.inspectionSummary.rectificationRate}%`}}</b></div></div><p v-else class="coord-empty-note">暂无已提交的排查反馈，地市办理后将汇总显示。</p><p v-if="detail.inspectionSummary.reportedCities" class="coord-form-note">按各市填报数量合计，同一企业或车辆跨市填报时可能重复计数。</p><ol class="coord-plain-checklist"><li v-for="item in detail.checklist" :key="item.id">{{item.label}}</li></ol></section>
  <section class="coord-detail-section"><header><h3>地市办理与反馈</h3><span class="pm-muted">{{detail.assignments.length}} 个责任地市</span></header><article v-for="assignment in detail.assignments" :key="assignment.id" class="coord-assignment"><header><div><strong>{{assignment.cityName}}</strong><el-tag size="small" effect="plain">{{assignmentRoles[assignment.role]}}</el-tag></div><el-tag size="small" :type="assignment.status==='CLOSED'?'success':assignment.status==='SUBMITTED'?'warning':'info'">{{assignmentStatuses[assignment.status]}}</el-tag></header><p class="coord-assignment-times">响应 {{dateTime(assignment.respondedAt)}} · 提交 {{dateTime(assignment.submittedAt)}}</p><InspectionReportFields v-if="assignment.report" :model-value="assignment.report" :checklist="detail.checklist" readonly/><p class="coord-prose">{{assignment.feedback||'等待属地办理并提交反馈。'}}</p><p v-if="assignment.evidenceNote" class="coord-basis">材料说明：{{assignment.evidenceNote}}</p><p v-if="assignment.reviewComment" class="coord-review-comment">省级复核意见：{{assignment.reviewComment}}</p><footer v-if="canWrite"><el-button v-if="assignment.status==='SUBMITTED'" :disabled="saving" @click="act('RETURN',assignment)">退回补充</el-button><el-button v-if="assignment.status==='SUBMITTED'" type="primary" :disabled="saving" @click="act('CLOSE',assignment)">复核办结</el-button><el-button v-if="['SUBMITTED','CLOSED'].includes(assignment.status)" link type="primary" @click="followUp(assignment)">发起整改督办</el-button></footer></article></section>
  <section class="coord-detail-section"><h3>过程记录</h3><el-timeline><el-timeline-item v-for="(log,index) in detail.logs" :key="index" :timestamp="dateTime(log.at)"><strong>{{logLabels[log.action]||'事项更新'}}</strong><p class="coord-prose">{{log.comment||log.content}} · {{log.actorName}}</p></el-timeline-item></el-timeline></section>
</template></ProvincePageState><template #footer><div v-if="detail&&canWrite" class="coord-detail-actions"><template v-if="detail.status==='DRAFT'"><el-button :disabled="saving" @click="emit('edit',detail)">编辑草稿</el-button><el-button type="primary" :loading="saving" @click="act('DISPATCH')">确认派发</el-button></template><el-button v-else-if="canCloseAll" type="primary" :loading="saving" :icon="ClipboardCheck" @click="act('CLOSE')">整体复核办结</el-button><span v-else class="pm-muted">{{detail.status==='CLOSED'?'事项已办结，办理记录保留供查阅。':'等待地市反馈，或在上方逐市复核。'}}</span></div></template></el-drawer></template>
